package graphicsgo

import (
	"encoding/json"
	"os"
	"testing"
)

type cffMapCase struct {
	Name    string                         `json:"name"`
	Scale   int64                          `json:"scale"`
	Edges   []CFFHintEdgeFixedExperimental `json:"edges"`
	Inputs  []int64                        `json:"inputs"`
	Outputs []int64                        `json:"outputs"`
}

func TestCFFHintMapFixedIndependentOracle(t *testing.T) {
	// Frozen numeric-only oracle generated by an independent offline Python
	// evaluator implementing the FreeType source's 16.16 selection/rounding.
	b, err := os.ReadFile(privateFixturePath(t, "oracle-hintmap-fixed"))
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Cases []cffMapCase `json:"cases"`
	}
	if err = json.Unmarshal(b, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Cases) < 8 {
		t.Fatalf("insufficient independent cases: %d", len(fixture.Cases))
	}
	for _, c := range fixture.Cases {
		t.Run(c.Name, func(t *testing.T) {
			m, e := NewCFFHintMapFixedExperimental(c.Scale, c.Edges)
			if e != nil {
				t.Fatal(e)
			}
			if len(c.Inputs) != len(c.Outputs) {
				t.Fatal("bad fixture")
			}
			for j, y := range c.Inputs {
				got, e := m.MapY(y)
				if e != nil {
					t.Fatalf("y=%d: %v", y, e)
				}
				if got != c.Outputs[j] {
					t.Fatalf("y=%d got=%d expected=%d", y, got, c.Outputs[j])
				}
			}
		})
	}
}
func TestCFFHintMapFixedRejectsBadAndNoMutate(t *testing.T) {
	for _, e := range [][]CFFHintEdgeFixedExperimental{
		{{CharacterY: 5, DeviceY: 1}, {CharacterY: 4, DeviceY: 2}},
		{{CharacterY: 4, DeviceY: 2}, {CharacterY: 5, DeviceY: 1}},
		{{CharacterY: 0, DeviceY: 0, Scale: -1}},
		{{CharacterY: 0, DeviceY: 0, Scale: 1 << 32}},
	} {
		if _, err := NewCFFHintMapFixedExperimental(1<<16, e); err == nil {
			t.Fatalf("accepted invalid map: %+v", e)
		}
	}
	if _, err := NewCFFHintMapFixedExperimental(0, nil); err == nil {
		t.Fatal("zero scale")
	}
	e := []CFFHintEdgeFixedExperimental{{CharacterY: 0, DeviceY: 100, Scale: 1 << 16}}
	m, err := NewCFFHintMapFixedExperimental(1<<16, e)
	if err != nil {
		t.Fatal(err)
	}
	e[0].DeviceY = 200
	v, err := m.MapY(0)
	if err != nil || v != 100 {
		t.Fatalf("mutable edge alias: %d %v", v, err)
	}
	if _, err = m.MapY(1 << 32); err == nil {
		t.Fatal("accepted out-of-range Y")
	}
}
